<?php if(!$images): ?><p class="empty">هنوز تصویری منتشر نشده است.</p><?php else: ?><div class="masonry"><?php foreach($images as $cardIndex=>$im): ?><article class="pin<?= isset($mobileLimit)&&$cardIndex>=$mobileLimit?' hs-desktop-extra':'' ?><?= isset($desktopLimit)&&$cardIndex>=$desktopLimit?' hs-mobile-extra':'' ?>" data-card-id="<?= (int)$im['id'] ?>"><div class="imagebox"><a href="<?= e(url('image',['id'=>$im['id']])) ?>"><img loading="lazy" decoding="async" src="<?= e(url('media',['id'=>$im['id']])) ?>" srcset="<?= e(url('media',['id'=>$im['id']])) ?> 550w, <?= e(url('media',['id'=>$im['id'],'size'=>'large'])) ?> 1200w" sizes="(max-width:550px) 46vw, 240px" width="<?= (int)$im['width'] ?>" height="<?= (int)$im['height'] ?>" alt="<?= e(Namira\PublicPresentation::imageTitle($im)) ?>"></a><?php if($im['download_allowed']??1): ?><a class="download" href="<?= e(url('download',['id'=>$im['id']])) ?>" aria-label="دانلود تصویر" title="دانلود تصویر"><?= Namira\MobileNavigation::icon('download') ?></a><?php endif ?></div><div class="meta"><a href="<?= e(url('profile',['id'=>$im['martyr_id']])) ?>"><b>شهید <?= e((($im['display_name']??'')?:($im['first_name'].' '.$im['last_name']))) ?></b><small><?= e(implode(' | ',array_filter([$im['topic_label']??'',$im['public_city']??'']))) ?></small></a></div></article><?php endforeach ?></div><?php endif ?>
